local config = {
  ui_story_31230401_A1_dialog_content = "PlayerName! Maaf sudah merepotkanmu...",
  ui_story_31230401_A2_dialog_content = "Tidak apa-apa, kok! Ayo, kuantar sampai ke pintu keluar.",
  ui_story_31230401_A3_dialog_content = "Ah! T-terima kasih...",
  ui_story_31230401_A4_dialog_content = "Kamu terlihat agak gugup. Kamu yakin semua baik-baik saja?",
  ui_story_31230401_A5_dialog_content = "Pekerjaanku di Gannon City menumpuk... Mungkin aku akan bekerja lembur sampai lewat tengah malam nanti...",
  ui_story_31230401_A6_dialog_content = "Sebaiknya sesekali kamu juga istirahat, Cordy. Kalau kamu sampai sakit, pasti banyak pekerjaanmu akan tertunda, tahu...",
  ui_story_31230401_A7_dialog_content = "Baiklah! Akan kuingat itu!",
  ui_story_31230401_A8_dialog_content = "<color=#e8d9bb>Tiga hari kemudian...</color>",
  ui_story_31230401_1_dialog_content = "Hoi, Navigator! Kamu sudah dengar belum?",
  ui_story_31230401_2_dialog_content = "Dengar apa?",
  ui_story_31230401_3_dialog_content = "Tentang <color=#FFB400>Cordy</color>! Terjadi sesuatu padanya!",
  ui_story_31230401_4_dialog_content = "Dia terlibat dalam kecelakaan pagi ini di Gannon City!",
  ui_story_31230401_5_dialog_content = "Pokoknya dia mengalami kondisi vegetatif gara-gara sebuah benda yang terbang tinggi!",
  ui_story_31230401_6_dialog_content = "<size=45>Apa?! Yang benar saja?!</size>",
  ui_story_31230401_7_dialog_content = "Ganti haluan! Kita akan langsung pergi ke Gannon City, kecepatan penuh!",
  ui_story_31230401_8_dialog_content = "Ruang rawat...",
  ui_story_31230401_9_dialog_content = "Di mana ruang rawatnya?",
  ui_story_31230401_10_dialog_content = "Kenapa kamu sangat terburu-buru, sih?",
  ui_story_31230401_11_dialog_content = "Katakan saja di mana ruang rawatnya!",
  ui_story_31230401_12_dialog_content = "D-di belakang, sebelah kiri... Kamu mau ke mana? Apa terjadi sesuatu?",
  ui_story_31230401_13_dialog_content = "Cordy!",
  ui_story_31230401_14_dialog_content = "... Hah? Kamu baik-baik saja...?",
  ui_story_31230401_15_dialog_content = "A-aku tidak apa-apa. Terima kasih...",
  ui_story_31230401_16_dialog_content = "Lalu bagaimana dengan kabar itu? Kudengar... Kudengar kamu terluka parah!",
  ui_story_31230401_17_dialog_content = "Oh, yang itu? Yah... Aku memang cedera, tapi...",
  ui_story_31230401_18_dialog_content = "Tapi?",
  ui_story_31230401_19_dialog_content = "Anu... Bukan masalah besar, kok! Sebentar lagi juga sembuh!",
  ui_story_31230401_20_dialog_content = "Jadi, apa yang sebenarnya...",
  ui_story_31230401_21_dialog_content = "Aduh, jadi ribut-ribut begini... Pergelangan kakimu cuma terkilir, 'kan?!",
  ui_story_31230401_22_dialog_content = "Lo? Revy? Kok kamu juga di sini?",
  ui_story_31230401_23_dialog_content = "Iya, aku kemari untuk minta resep obat.",
  ui_story_31230401_24_dialog_content = "Kamu juga sakit? Tumben...",
  ui_story_31230401_25_dialog_content = "Betul sekali. Aku sedang berada di ambang kematian saat berurusan dengan kotak sekring listrik bertegangan tinggi. Lalu tiba-tiba aku terlalu berlebihan saat meregangkan punggungku! Hahaha!",
  ui_story_31230401_26_dialog_content = "Kenapa kamu sampai \"berada di ambang kematian\" saat berurusan dengan kotak sekring listrik?! Itu sangat berbahaya, tahu!",
  ui_story_31230401_27_dialog_content = "Lalu bisa-bisanya kamu hanya mengalami sakit punggung?!",
  ui_story_31230401_28_dialog_content = "Jangan kaget begitu, dong. Aku menguji keberanianku setiap hari dengan melawan segala jenis musuh. Begitulah caraku menyempurnakan teknikku.",
  ui_story_31230401_29_dialog_content = "... Baiklah. Eh, sebentar, tadi kamu bilang pergelangan kaki Cordy cuma terkilir?",
  ui_story_31230401_30_dialog_content = "Benar. Dia sedang berjalan, lalu tiba-tiba BRAK!",
  ui_story_31230401_31_dialog_content = "Pergelangan kakinya terkilir.",
  ui_story_31230401_32_dialog_content = "...",
  ui_story_31230401_33_dialog_content = "Aku melihatnya sendiri. Aku juga yang membawanya kemari.",
  ui_story_31230401_34_dialog_content = "Lalu... Kenapa tadi Vice mengatakan bahwa Cordy... mengalami kondisi vegetatif?",
  ui_story_31230401_35_dialog_content = "Kondisi vegetatif? Semacam vegetasi pada sayuran?",
  ui_story_31230401_36_dialog_content = "Hah? Tapi... Tapi, aku tak mau berubah jadi sayuran!",
  ui_story_31230401_37_dialog_content = "Apa jangan-jangan ada miskomunikasi, ya...?",
  ui_story_31230401_38_dialog_content = "Ah! Apa yang terjadi, Cordy? Kamu jatuh lalu pergelangan kakimu terkilir?",
  ui_story_31230401_39_dialog_content = "Sudah dengar tentang Cordy belum? Sepertinya dia jatuh dari ketinggian lalu kakinya patah... Gadis yang malang.",
  ui_story_31230401_40_dialog_content = "Hoi, aku baru saja mendapat kabar! Ini tentang Cordy... Katanya, dia tersandung di tangga, lalu kakinya harus diamputasi!",
  ui_story_31230401_41_dialog_content = "Hoi, Vice! Sudah dengar belum?",
  ui_story_31230401_42_dialog_content = "Ada orang yang melemparkan kaki palsunya ke tangga, lalu benda itu mengenai Cordy dan membuatnya koma!",
  ui_story_31230401_43_dialog_content = "Kurasa itu tidak sepenuhnya mustahil...",
  ui_story_31230401_44_dialog_content = "C-cukup! Sudahlah... Ini sama sekali bukan masalah besar...",
  ui_story_31230401_45_dialog_content = "Memalukan sekali... Aku jadi sangat merepotkan orang lain gara-gara masalah kecil...",
  ui_story_31230401_46_dialog_content = "Ini sama sekali bukan masalah kecil! Pergelangan kaki yang terkilir bisa berakibat fatal! Bagaimana kalau kejadiannya saat kamu berada di tangga...?",
  ui_story_31230401_47_dialog_content = "Sebenarnya, kejadiannya memang seperti itu, sih. Pergelangan kakinya terkilir saat dia berjalan menuruni tangga, lalu dia terjatuh.",
  ui_story_31230401_48_dialog_content = "Apa?! Jadi, kejadian sebenarnya memang begitu?!",
  ui_story_31230401_49_dialog_content = "Ini bukan apa-apa, kok! Hanya sedikit tergores saja...",
  ui_story_31230401_50_dialog_content = "Maaf karena kamu sudah repot-repot kemari untuk menjengukku, PlayerName... Tapi, aku tidak apa-apa! Sungguh!",
  ui_story_31230401_51_dialog_content = "Lihat, sudah lebih baik, kok! Iya, 'kan?",
  ui_story_31230401_52_dialog_content = "Aduh...",
  ui_story_31230401_53_dialog_content = "Kakimu masih sakit, jangan coba-coba menyembunyikannya! Sini, duduk saja. Jangan memaksakan diri.",
  ui_story_31230401_54_dialog_content = "...",
  ui_story_31230401_55_dialog_content = "Kenapa kamu kelihatan sangat sedih, Cordy?",
  ui_story_31230401_56_dialog_content = "... Maafkan aku, Navigator.",
  ui_story_31230401_57_dialog_content = "Gara-gara terluka, aku jadi tak bisa menyelesaikan banyak pekerjaan...",
  ui_story_31230401_58_dialog_content = "Kalau memikirkannya...",
  ui_story_31230401_59_option_content = "Jangan khawatir. Serahkan saja padaku.",
  ui_story_31230401_60_dialog_content = "H-hah? Tidak! Jangan!",
  ui_story_31230401_61_dialog_content = "Aku justru akan merasa lebih bersalah kalau kamu membantuku menyelesaikan pekerjaanku, PlayerName!",
  ui_story_31230401_62_dialog_content = "Selain itu, ini bukan pekerjaan yang tepat untuk Navigator!",
  ui_story_31230401_63_option_content = "Ini bukan salahmu, Cordy.",
  ui_story_31230401_64_dialog_content = "T-tapi, kalau saja tadi aku lebih hati-hati, aku...",
  ui_story_31230401_65_dialog_content = "Dia benar, Cordy. Selain itu, pergelangan kaki terkilir adalah kejadian yang cukup umum.",
  ui_story_31230401_66_dialog_content = "Serahkan saja tugasmu pada PlayerName. Biar dia yang mengurus sisanya.",
  ui_story_31230401_67_dialog_content = "Eh?",
  ui_story_31230401_68_dialog_content = "H-hah? Tidak! Jangan!",
  ui_story_31230401_69_dialog_content = "Aku justru akan merasa lebih bersalah kalau kamu membantuku menyelesaikan pekerjaanku, PlayerName!",
  ui_story_31230401_70_dialog_content = "Selain itu, ini bukan pekerjaan yang tepat untuk Navigator!",
  ui_story_31230401_71_dialog_content = "Kamu salah. Melindungi semua orang dan membantu memikul beban mereka adalah tugas utamaku.",
  ui_story_31230401_72_dialog_content = "Kalau kamu kesulitan, Cordy, dengan senang hati aku akan selalu membantumu!",
  ui_story_31230401_73_dialog_content = "PlayerName...",
  ui_story_31230401_74_dialog_content = "Apa kamu punya uraian tugas atau semacam daftar?",
  ui_story_31230401_75_dialog_content = "Nih.",
  ui_story_31230401_76_dialog_content = "Kok kamu menyimpannya...?",
  ui_story_31230401_77_dialog_content = "Benda itu tadinya ada di meja. Cordy membolak-baliknya seharian ini sambil berdesah setiap dia membuka halaman baru.",
  ui_story_31230401_78_dialog_content = "Aaah! Tidak, tidak, tidak! Mau bagaimanapun juga, aku tak bisa kalau harus begini!",
  ui_story_31230401_79_dialog_content = "Sini, serahkan saja padaku! Aku sudah mendingan, dan...",
  ui_story_31230401_80_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_31230401_81_dialog_content = "Ayolah, kamu istirahat saja, ya...?",
  ui_story_31230401_82_dialog_content = "Tugas pertama dalam daftar... Ini tempatnya, 'kan? Aku tidak begitu mengenal Gannon City...",
  ui_story_31230401_83_dialog_content = "Halo! Namaku PlayerName, dan aku bertugas menggantikan Cordy hari ini! Aku kemari untuk meminta keterangan tentang kasus yang terjadi kemarin!",
  ui_story_31230401_84_dialog_content = "Oh, maksudmu Peace Officer kecil itu? Terima kasih, tapi pencurinya sudah tertangkap.",
  ui_story_31230401_85_dialog_content = "Sampaikan ucapan terima kasihku padanya, ya, Caelestite? Kalau bukan berkat dia, kasus ini tak akan bisa diselesaikan dengan sangat lancar.",
  ui_story_31230401_86_dialog_content = "Aku mengerti!",
  ui_story_31230401_87_dialog_content = "Halo! Namaku PlayerName, dan aku bertugas menggantikan Cordy hari ini untuk melakukan pemeriksaan keselamatan kebakaran rutin!",
  ui_story_31230401_88_dialog_content = "Aku sudah menyingkirkan setiap hal yang berpotensi bahaya di sini! Ini semua berkat kerja kerasnya!",
  ui_story_31230401_89_dialog_content = "Ambillah, ini surat ucapan terima kasih dariku. Maukah kamu membantuku mengantarkannya?",
  ui_story_31230401_90_dialog_content = "A-aku mengerti!",
  ui_story_31230401_91_dialog_content = "(Sepertinya Cordy cukup disukai di Gannon City... Semua orang tampaknya menyadari betapa rajinnya dia sebagai Peace Officer.)",
  ui_story_31230401_92_dialog_content = "Halo! Namaku PlayerName, dan aku bertugas menggantikan Cordy hari ini untuk... Membantumu menyiram tanaman?",
  ui_story_31230401_93_dialog_content = "(... Kenapa makin lama tugasnya makin menyimpang dari tugas rutin seorang Peace Officer?)",
  ui_story_31230401_94_dialog_content = "Terima kasih, Cordy...",
  ui_story_31230401_95_dialog_content = "Anu, P-pak? Aku bukan Cordy, aku hanya menggantikannya...",
  ui_story_31230401_96_dialog_content = "Kami sangat berterima kasih atas segala bantuanmu. Ambillah bendera sutra ini...",
  ui_story_31230401_97_dialog_content = "Lalu panji ini juga... Tolong ambillah sebagai ucapan terima kasih kami...",
  ui_story_31230401_98_dialog_content = "Eh... A-aku mengerti...",
  ui_story_31230401_99_dialog_content = "Jaga dirimu, Cordy... Lagi pula sepertinya kamu jarang istirahat...",
  ui_story_31230401_100_dialog_content = "Jangan lupa, jaga dirimu baik-baik...",
  ui_story_31230401_101_dialog_content = "(Genggaman tangan pria ini sangat kuat...)",
  ui_story_31230401_102_dialog_content = "Aduh... Banyak sekali barang yang harus kubawa. Lama-lama jadi makin berat...",
  ui_story_31230401_103_dialog_content = "H-halo! Namaku PlayerName, dan aku bertugas menggantikan Cordy hari ini untuk...",
  ui_story_31230401_104_dialog_content = "... Mengambil botol susu kosongmu?",
  ui_story_31230401_105_dialog_content = "Nyah! Aduh, leganya!",
  ui_story_31230401_106_dialog_content = "Phylishy! Lama tidak berjumpa!",
  ui_story_31230401_107_dialog_content = "Kudengar Cordy mengalami kecelakaan kecil. Sepertinya dia membujukmu untuk mengerjakan tugasnya, ya?",
  ui_story_31230401_108_dialog_content = "Wah, kamu memang pria yang sem-purr-na, Navigator!",
  ui_story_31230401_109_dialog_content = "Nih, ini seluruh botol susuku untuk minggu ini! Selamat mengangkut, Tn. Pengantar Susu!",
  ui_story_31230401_110_dialog_content = "<color=#e8d9bb><size=45>BRUK!</size></color>",
  ui_story_31230401_111_dialog_content = "E-empat peti?! Tapi, berarti isinya ada empat puluh delapan botol! Kamu minum empat puluh delapan botol susu setiap pekan?!",
  ui_story_31230401_112_dialog_content = "Memangnya kenapa? Terlalu berat, ya? Cordy tidak pernah mengeluh, tahu? Dia selalu mengangkutnya tanpa banyak omong!",
  ui_story_31230401_113_dialog_content = "Bisa-bisanya kamu tak enak hati sedikit pun karena membuatnya melakukan hal seperti ini!",
  ui_story_31230401_114_dialog_content = "Argh... Kakiku... Rasanya sangat lemah...",
  ui_story_31230401_115_dialog_content = "Kalau tadi aku tak meminta tas besar ini kepada seseorang, mana mungkin aku bisa menyeret semua hadiah dan surat ucapan terima kasih ini...",
  ui_story_31230401_116_dialog_content = "Selain itu, tak kusangka ada seseorang yang benar-benar memberinya pohon uang sebagai hadiah...",
  ui_story_31230401_117_dialog_content = "Siapa juga yang membutuhkannya sekarang...",
  ui_story_31230401_118_dialog_content = "...",
  ui_story_31230401_119_dialog_content = "Hmm? Apa yang barusan itu suara seseorang, ya?",
  ui_story_31230401_120_dialog_content = "... Berhentilah sebentar.",
  ui_story_31230401_121_dialog_content = "Maaf! Aku benar-benar minta maaf! Aku... aku akan mencari sebelah sepatuku, kumohon tunggu sebentar...",
  ui_story_31230401_122_dialog_content = "Baiklah, sudah cukup minta maafnya. Aku tidak kemari untuk menanyakan pekerjaanmu.",
  ui_story_31230401_123_dialog_content = "Inspector...",
  ui_story_31230401_124_dialog_content = "...",
  ui_story_31230401_125_dialog_content = "Apa masih sakit?",
  ui_story_31230401_126_dialog_content = "S-sedikit. Aku baru saja minum obat, jadi rasanya sudah lebih baik!",
  ui_story_31230401_127_dialog_content = "Pergelangan kaki kirimu?",
  ui_story_31230401_128_dialog_content = "Benar. Sekali lagi, maafkan aku karena sudah merepotkan semua orang, Inspector...",
  ui_story_31230401_129_dialog_content = "Bahkan PlayerName sampai repot-repot menjenguk dan membantuku...",
  ui_story_31230401_130_dialog_content = "Aku sudah tahu. Beberapa waktu lalu aku menerima kabar bahwa ada seorang Caelestite yang melakukan berbagai pekerjaan di Gannon City hari ini...",
  ui_story_31230401_131_dialog_content = "Ternyata pekerjaan itu adalah tugas-tugas yang biasanya kamu kerjakan sehari-hari.",
  ui_story_31230401_132_dialog_content = "...",
  ui_story_31230401_133_dialog_content = "Kamu adalah Peace Officer, Cordy. Bukan pekerja serabutan.",
  ui_story_31230401_134_dialog_content = "Hah? T-tapi, orang-orang itu... mereka butuh bantuan...!",
  ui_story_31230401_135_dialog_content = "Ada banyak orang yang membutuhkan bantuan di dunia. Apa kamu bisa membantu mereka semua?",
  ui_story_31230401_136_dialog_content = "Tugasmu adalah melindungi perdamaian dan ketertiban di kota kita.",
  ui_story_31230401_137_dialog_content = "Nemesis!",
  ui_story_31230401_138_dialog_content = "PlayerName. Tadinya aku bertanya-tanya kapan kamu akan kembali.",
  ui_story_31230401_139_dialog_content = "Izinkan aku mengatakan beberapa hal tentang Cordy! Dia benar-benar orang yang sangat rajin!",
  ui_story_31230401_140_dialog_content = "Setiap orang yang kutemui hari ini mengatakan hal-hal yang luar biasa tentang dia!",
  ui_story_31230401_141_dialog_content = "PlayerName...",
  ui_story_31230401_142_dialog_content = "Intinya?",
  ui_story_31230401_143_dialog_content = "Intinya? Bukankah \"inti\" dari pekerjaannya adalah melayani masyarakat?",
  ui_story_31230401_144_dialog_content = "Melindungi perdamaian dan ketertiban memang bisa dilakukan dengan menegakkan hukum... Tapi, itu juga bisa dilakukan dalam bentuk pelayanan terhadap masyarakat dengan hati yang baik dan penuh perhatian!",
  ui_story_31230401_145_dialog_content = "Yang Cordy lakukan adalah...",
  ui_story_31230401_146_dialog_content = "Sial! Kakiku tertekuk!!",
  ui_story_31230401_147_dialog_content = "<color=#e8d9bb><size=45>BRAK!</size></color>",
  ui_story_31230401_148_dialog_content = "Apa-apaan... Benda-benda apa ini?",
  ui_story_31230401_149_dialog_content = "M-maaf! Ini untuk Cordy!",
  ui_story_31230401_150_dialog_content = "Pohon uang?",
  ui_story_31230401_151_dialog_content = "Begitulah! Aneh, 'kan? Aku juga tidak tahu kenapa ada orang yang ingin memberi Cordy satu!",
  ui_story_31230401_152_dialog_content = "... Hehehe.",
  ui_story_31230401_153_dialog_content = "I-Inspector...?",
  ui_story_31230401_154_dialog_content = "Hahahahaha!",
  ui_story_31230401_155_dialog_content = "Tidak perlu gugup, Cordy. Lagi pula, sudah kubilang aku tidak kemari untuk menanyakan pekerjaanmu.",
  ui_story_31230401_156_dialog_content = "Justru sebaliknya. Aku kemari untuk mengonfirmasi sesuatu...",
  ui_story_31230401_157_dialog_content = "Aku datang untuk menanyakan apakah kamu masih bersedia melakukan tugasmu sebagai Peace Officer.",
  ui_story_31230401_158_dialog_content = "H-hah? Maksudnya?",
  ui_story_31230401_159_dialog_content = "Pekerjaan ini lebih berat daripada dugaanku, dan cakupan tanggung jawabnya benar-benar terlalu luas.",
  ui_story_31230401_160_dialog_content = "Aku benar-benar paham jika kamu memutuskan untuk mundur dari pekerjaan ini.",
  ui_story_31230401_161_dialog_content = "Tapi, jika kamu mau melanjutkannya, aku...",
  ui_story_31230401_162_dialog_content = "Aku ingin terus bekerja!",
  ui_story_31230401_163_dialog_content = "Tidak... Aku harus terus bekerja!",
  ui_story_31230401_164_dialog_content = "Daftar tugas harianku... Penuh dengan kepercayaan dan harapan semua orang padaku!",
  ui_story_31230401_165_dialog_content = "Meskipun hanya tugas-tugas sederhana, seperti menyiram tanaman atau membantu mereka membuang sampah...",
  ui_story_31230401_166_dialog_content = "Semua itu penting untuk kemakmuran Illumina Federation, dan untuk pekerjaanku sebagai Peace Officer!",
  ui_story_31230401_167_dialog_content = "(Sekarang dia menganggap bahwa melakukan pekerjaan rumah tangga orang itu bagian dari moralitas?!)",
  ui_story_31230401_168_dialog_content = "Mungkin aku hanya ditugaskan di salah satu wilayah kecil di Gannon City, tapi setiap jalan dan warganya...",
  ui_story_31230401_169_dialog_content = "Aku bersumpah akan melakukan segalanya untuk melindungi mereka!",
  ui_story_31230401_170_dialog_content = "Aku akan mengemban tanggung jawab untuk melindungi seluruh kota kita jika memang harus! Sampai ke sudut terkecilnya!",
  ui_story_31230401_171_dialog_content = "Kamu yakin?",
  ui_story_31230401_172_dialog_content = "<size=45>Tentu saja!</size>",
  ui_story_31230401_173_dialog_content = "Baiklah kalau begitu. Aku menghargai antusiasmemu, tapi pemulihanmu lebih penting dari pekerjaan. Sekarang beristirahatlah. Kita akan mendiskusikan pekerjaanmu di lain waktu. Itu perintah.",
  ui_story_31230401_174_dialog_content = "Baik, Inspector!",
  ui_story_31230401_175_dialog_content = "Nah, sekarang kamu jadi lebih ceria, ya, Cordy? Sepertinya kakimu juga sudah sembuh!",
  ui_story_31230401_176_dialog_content = "Hah? Wah, benar juga! Obat Nona Joya benar-benar manjur!",
  ui_story_31230401_177_dialog_content = "Tapi, jangan lupa perhatikan langkahmu lain kali.",
  ui_story_31230401_178_dialog_content = "Iya! ...T-tapi, kadang aku memang kesulitan melihat apa yang ada di depanku.",
  ui_story_31230401_179_dialog_content = "Pandanganku selalu terhalang sepanjang waktu. Kuharap aku bisa menemukan solusinya...",
  ui_story_31230401_180_dialog_content = "...",
  ui_story_31230401_181_dialog_content = "...",
  ui_story_31230401_182_dialog_content = "Hahaha! Sepertinya ini masalah yang tak kupahami!",
  ui_story_31230401_183_dialog_content = "(Kadang suara tawa Nemesis terdengar sangat tak mengenakkan...)",
